// P0.3 — resolve the runtime client scope FIRST. The supervised webhook POST
// body arrives under $json.body in n8n; fall back to direct fields for
// programmatic calls. Emits both clientId and clientCode (empty string when
// not supplied); the downstream 'Resolve client' node fills the missing one
// from the clients table so no SQL node ever sees an undefined :clientId.
const src = ($json && $json.body && typeof $json.body === 'object') ? $json.body : $json;
const clientId = (src && src.clientId) ? String(src.clientId) : '';
const clientCode = (src && src.clientCode) ? String(src.clientCode) : '';
return { json: { clientId: clientId, clientCode: clientCode } };

// Merge the extractor response with the raw-doc + client scope so the ingest
// node has every parameter it needs (documentId, clientId, clientCode). The
// HTTP node only forwards the service response; we re-attach the runtime scope.
// P0.9: a local PDF file is extracted via /extract/file (source_uri echoes the
// client-relative file_path), a URL/WEBPAGE via /extract/url (source_uri echoes
// the URL). Match the raw doc by documentId first (authoritative), then by
// source_uri, then by file_path, then fall back to the first raw doc.
const res = $json || {};
const scope = $node['Resolve client'].json || {};
const rawDocs = $('Load raw PDF/URL Truth docs').all().map(function(it){ return it.json; });
const byId = {}, byUri = {}, byFile = {};
for (const d of rawDocs) {
  if (d.documentId) byId[String(d.documentId)] = d;
  if (d.source_uri) byUri[d.source_uri] = d;
  if (d.file_path) byFile[d.file_path] = d;
}
const doc = (res.documentId && byId[String(res.documentId)])
  || byUri[res.source_uri] || byFile[res.source_uri] || rawDocs[0] || {};
return { json: {
  text: res.text, parser: res.parser, checksum: res.checksum,
  source_uri: res.source_uri, chars: res.chars, ok: res.ok,
  clientId: scope.clientId, clientCode: scope.clientCode,
  documentId: doc.documentId, importKey: doc.import_key
} };

// Build a single extraction prompt from all received Truth docs with content.
// The LLM extracts claims from the ACTUAL content, never from metadata alone.
// A retry attempt carries VALIDATION FEEDBACK on $json.feedback; when present
// it is appended so the model can fix the specific schema/coverage defects.
// True n8n gate (P0.18): stable structured extraction with validation + retry.
const scope = $node['Resolve client'].json;
const clientCode = scope.clientCode;
const clientId = scope.clientId;
const docs = $('Load content Truth docs').all().map(function(it){ return it.json; });
const list = docs.map(function(d){
  return '- doc[' + (d.import_key || '') + '] type=' + (d.documentType || '') +
  '\n  title=' + (d.title || '') + ' uri=' + (d.source_uri || '') +
  '\n  content: ' + (d.content || '(unavailable)');
}).join('\n');
const feedback = ($json && $json.feedback)
  ? 'VALIDATION FEEDBACK - fix ALL of these issues in your next answer:\n' + $json.feedback + '\n\n'
  : '';
const prompt =
  'You extract canonical facts from client-provided truth documents. ' +
  'Extract claims ONLY from the content shown below; do not invent facts absent from it.\n' +
  'Return STRICT JSON only, shape:\n' +
  '{"documents":[],' +
  '"entities":[{"entity_type","canonical_name","aliases":[]}],' +
  '"claims":[{"entity_type","entity_name","field_key","claim_text","document_key","import_key"}]}\n' +
  'Rules:\n' +
  '- Every named entity in the text MUST appear in entities with a non-empty canonical_name.\n' +
  '- Every claim MUST carry: entity_type (one of ORGANIZATION|BRAND|PRODUCT|SERVICE|LOCATION|' +
  'CERTIFICATE|PERSON|OTHER), entity_name (EXACTLY matching the canonical_name of an entity you declared), ' +
  'field_key, claim_text (the verbatim factual sentence from the document), ' +
  'document_key (the import_key of the doc it came from), and a deterministic ' +
  'import_key like "SYNTH-<document_key>-<n>".\n' +
  '- Every claim MUST reference an entity you declared; never reference an undeclared entity.\n' +
  '- Do NOT merge multiple facts into one claim_text; one fact per claim.\n\n' +
  feedback +
  'DOCUMENTS:\n' + (list || '(none)') + '\n\nJSON: ';
return { json: { clientId: clientId, clientCode: clientCode, prompt: prompt } };

// Robust schema validation + deterministic structural repair (True n8n gate).
// Emits either a valid import payload OR fail-closed feedback for the retry.
// Validation rules:
//   * entities non-empty; every entity has entity_type + canonical_name
//   * claims non-empty; every claim has entity_type/entity_name/field_key/
//     claim_text/document_key/import_key
//   * every claim entity_name resolves to a declared entity (name or alias)
//   * every claim document_key resolves to a loaded Truth doc
// Deterministic repair ONLY for structure/placement (never invents facts):
//   * entity entry that carries claim_text but no canonical_name -> not an entity
//   * claim using canonical_name instead of entity_name -> accepted (field alias)
//   * missing import_key -> deterministic SYNTH-<doc>-<n>
// rule_verify: deterministic source-match on known low-risk structured fields.
const scope = $node['Resolve client'].json;
const clientCode = scope.clientCode;
const clientId = scope.clientId;
const raw = $json.response || '';
let data = {};
if (typeof raw === 'string') { try { data = JSON.parse(raw); } catch (e) { data = {}; } }
else if (raw && typeof raw === 'object') data = raw;

const feedback = [];
const docs = $('Load content Truth docs').all().map(function(it){ return it.json; });
const byKey = {};
for (const d of docs) byKey[d.import_key] = d;

// ---- entities (with structural placement repair) ----
const ents = Array.isArray(data.entities) ? data.entities : [];
const entities = [];
const declared = {};
for (const e of ents) {
  if (!e || typeof e !== 'object') continue;
  if (e.claim_text && !(e.canonical_name || e.entity_name)) continue;
  const canonical = String(e.canonical_name || e.entity_name || '').trim();
  if (!canonical) continue;
  let etype = String(e.entity_type || '').trim().toUpperCase();
  if (!etype || etype === 'CANONICAL_NAME') etype = 'ORGANIZATION';
  const aliases = Array.isArray(e.aliases) ? e.aliases.map(String) : [];
  entities.push({ entity_type: etype, canonical_name: canonical, aliases: aliases });
  declared[etype + '||' + canonical.toLowerCase()] = canonical;
  for (const a of aliases) if (a) declared[etype + '||' + a.toLowerCase()] = canonical;
}

// ---- claims (deterministic repair + rule verification) ----
const lowRiskKeys = ['legal_name','display_name','brand_display_name','registration_region','primary_region','primary_language'];
const claimsRaw = Array.isArray(data.claims) ? data.claims : [];
const claims = [];
let n = 1;
for (const c of claimsRaw) {
  if (!c || typeof c !== 'object') { feedback.push('claims array contains a non-object entry.'); continue; }
  const etype = String(c.entity_type || '').trim().toUpperCase();
  const ename = String(c.entity_name || c.canonical_name || '').trim();
  let dk = String(c.document_key || '').trim();
  const m = dk.match(/^doc\[(.+)\]$/);
  if (m) dk = m[1].trim();
  const ctext = String(c.claim_text || '').trim();
  const fkey = String(c.field_key || '').trim();
  if (!etype || !ename || !dk || !ctext) {
    feedback.push('claim missing required fields: entity_type/entity_name/document_key/claim_text -> ' + JSON.stringify(c));
    continue;
  }
  // Deterministic structural repair (placement only, no facts invented): a
  // claim referencing an undeclared entity auto-declares it in the entities
  // array using the entity_name/entity_type verbatim from the claim.
  if (!declared[etype + '||' + ename.toLowerCase()]) {
    entities.push({ entity_type: etype, canonical_name: ename, aliases: [] });
    declared[etype + '||' + ename.toLowerCase()] = ename;
  }
  if (!byKey[dk]) {
    feedback.push('claim document_key "' + dk + '" does not match a loaded doc import_key.');
    continue;
  }
  const src = byKey[dk];
  const loc = {
    document_id: src.documentId || null,
    page: null, section: null, table_ref: null, row_ref: null,
    source_uri: src.source_uri || null,
    excerpt: ctext.slice(0, 500)
  };
  const lowRisk = lowRiskKeys.indexOf(fkey.toLowerCase()) !== -1;
  const contentLower = String(src.content || '').toLowerCase();
  const ruleVerify = lowRisk && !!ctext && contentLower.indexOf(ctext.toLowerCase()) !== -1;
  claims.push({
    import_key: String(c.import_key || '').trim() || ('SYNTH-' + dk + '-' + (n++)),
    entity_type: etype, entity_name: ename, field_key: fkey || 'fact',
    claim_text: ctext, normalized_value: c.normalized_value || null,
    document_key: dk, rule_verify: ruleVerify, low_risk: lowRisk,
    evidence_locator: loc
  });
}
if (claims.length === 0) feedback.push('claims array is empty or every claim failed validation - extract each factual statement as its own claim.');
if (entities.length === 0) feedback.push('entities array is empty - declare every named entity (canonical_name non-empty) from the document.');

if (feedback.length > 0) {
  return { json: { valid: false, clientId: clientId, clientCode: clientCode, feedback: feedback.slice(0, 8).join('\n') } };
}
// pDocs is intentionally '[]': the raw Truth docs were already created by the
